QString fresh(const QJsonArray &rows,QString prefix){QSet<QString> ids;for(auto v:rows)ids.insert(v.toObject()["id"].toString());int i=1;while(ids.contains(prefix+QString::number(i)))++i;return prefix+QString::number(i);}
